# Optional helper that regenerates the pages. Edit the .html files directly if you prefer.
P="+1 (343) 548-0271";E="FreshStartCleaningottawa@gmail.com"
NAV=[("index","Home"),("about","About"),("services","Services"),("residential","Residential"),("commercial","Commercial"),("move-in-out","Move In/Out"),("gallery","Gallery"),("faq","FAQ"),("contact","Contact")]
def page(f,title,body,hero=None):
    SUB=[("residential","Residential Cleaning"),("commercial","Commercial Cleaning"),("move-in-out","Move-In / Move-Out")]
    li=lambda k,n:f'<li><a href="{k}.html"{" class=on" if k==f else ""}>{n}</a></li>'
    sub="".join(f'<li><a href="{k}.html">{n}</a></li>' for k,n in SUB)
    ins=f in ("services","residential","commercial","move-in-out")
    nav=li("index","Home")+li("about","About")+f'<li class="dd"><a href="services.html"{" class=on" if ins else ""}>Services <span class="car">▾</span></a><ul class="sub"><li><a href="services.html">All Services</a></li>{sub}</ul></li>'+li("gallery","Gallery")+li("faq","FAQ")+li("contact","Contact")
    top=hero or f'<div class="phero"><div class="wrap"><span class="eyebrow">Fresh Start Pro Clean</span><h1>{title}</h1></div></div>'
    foot="".join(f'<li><a href="{k}.html">{n}</a></li>' for k,n in NAV[1:6])
    return f'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title} | Fresh Start Pro Clean – Ottawa Cleaning Company</title><meta name="description" content="Family-owned, registered and insured Ottawa cleaning company. Residential, commercial and move-in/out cleaning. Call {P}.">
<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600;700&family=Jost:wght@300;400;500&display=swap" rel="stylesheet"><link rel="stylesheet" href="css/style.css"></head><body>
<header><div class="wrap nav"><a class="brand" href="index.html"><img src="images/logo.jpg" alt="Fresh Start Pro Clean logo">Fresh Start</a><nav><button class="burger" aria-label="Menu">☰</button><ul>{nav}<li><a class="btn" href="booking.html">Book a Quote</a></li></ul></nav></div></header>
{top}{body}
<footer><div class="wrap"><div class="grid"><div><h4>Fresh Start Pro Clean</h4><p>Built by family, trusted by families. Registered and insured cleaning for Ottawa homes and workplaces.</p></div><div><h4>Explore</h4><ul>{foot}</ul></div><div><h4>Hours</h4><ul><li>Open now for bookings</li><li>Call or text any time</li><li>Free quotes</li></ul></div><div><h4>Contact</h4><ul><li><a href="tel:+13435480271">{P}</a></li><li><a href="mailto:{E}">{E}</a></li><li>Heron Rd, Ottawa, ON</li></ul></div></div><p class="copy">© 2026 Fresh Start Pro Clean. All rights reserved.</p></div></footer>
<script src="js/config.js"></script><script src="https://cdn.jsdelivr.net/npm/@emailjs/browser@4.4.1/dist/email.min.js"></script><script src="js/main.js"></script></body></html>'''
def head(e,h,l=""):return f'<div class="{"center " if l!="L" else ""}rv"><span class="eyebrow">{e}</span><h2>{h}</h2>{"" if l=="L" else ""}</div>'
def cards(items,cls="g3",num=False):
    return f'<div class="grid {cls}">'+"".join(f'<div class="card rv">{"<div class=n>%02d</div>"%(i+1) if num else ""}<h3>{t}</h3><p>{d}</p></div>' for i,(t,d) in enumerate(items))+'</div>'
def sp(img,e,h,txt,items,rev=False):
    return f'<section><div class="wrap split rv"><div{" style=order:2" if rev else ""}><span class="eyebrow">{e}</span><h2>{h}</h2><p class="lead">{txt}</p><ul class="tick">{"".join(f"<li>{i}</li>" for i in items)}</ul><p style="margin-top:28px"><a class="btn dk" href="booking.html">Get a Free Quote</a></p></div><img src="images/{img}" alt="{h}"></div></section>'
CTA=f'<section class="offer"><div class="wrap rv"><span class="eyebrow">Ready when you are</span><h2>Your Fresh Start Awaits</h2><p>Call or text {P}, or book online in two minutes and receive your quote by email.</p><a class="btn" href="booking.html">Book &amp; Get a Quote</a> &nbsp; <a class="btn ghost" href="tel:+13435480271">Call Us</a></div></section>'
SV=[("Residential Cleaning","Weekly, bi-weekly and monthly care for homes of every size, tailored to your routine."),("Deep Cleaning","A top-to-bottom reset that reaches the details a regular visit does not."),("Move-In / Move-Out","Appliances, cabinets and every surface, all included in one flat hourly rate."),("Commercial &amp; Offices","Reliable scheduled cleaning that keeps your workplace welcoming and professional."),("Clinics &amp; Dental Offices","Meticulous, health-conscious standards for patient-facing spaces."),("Daycare Centres","Careful, child-friendly cleaning for early-learning environments.")]
def ba(n,t):return f'<div class="rv"><div class="ba"><img src="images/ba{n}-after.jpg" alt="After {t}"><div class="bf"><img src="images/ba{n}-before.jpg" alt="Before {t}"></div><span class="tg" style="left:12px">BEFORE</span><span class="tg" style="right:12px">AFTER</span><div class="ln"></div><input type="range" min="0" max="100" value="50" aria-label="Compare before and after"></div><div class="cap">{t}</div></div>'
BA=[ba(1,"Kitchen Deep Clean"),ba(2,"Bathroom Restoration"),ba(3,"Move-Out Reset"),ba(4,"Office &amp; Clinic Space")]
def faq(q,a):return f'<details class="rv"><summary>{q}</summary><p>{a}</p></details>'
